package com.redhat.lightwell.service;

import java.math.BigDecimal;
import java.util.Optional;
import com.redhat.lightwell.model.Account;
import com.redhat.lightwell.model.AccountType;
import com.redhat.lightwell.model.Customer;
import com.redhat.lightwell.model.Transaction;
import com.redhat.lightwell.model.dto.StatementImportResponse;
import com.redhat.lightwell.repository.AccountRepository;
import com.redhat.lightwell.repository.TransactionRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class AtgStatementImportTest {
    @Mock private AccountRepository accounts;
    @Mock private TransactionRepository transactions;
    @Mock private AuditService audit;
    @InjectMocks private StatementImportService service;

    @Test
    void importsLowerCaseDeposit() {
        Customer customer = new Customer("Development", "Fixture", "fixture@example.invalid", "555-0100");
        Account account = new Account("ACC-ATG", AccountType.CHECKING, new BigDecimal("1000.00"), customer);
        when(accounts.findById(1L)).thenReturn(Optional.of(account));
        when(accounts.save(any(Account.class))).thenAnswer(call -> call.getArgument(0));
        when(transactions.save(any(Transaction.class))).thenAnswer(call -> call.getArgument(0));

        StatementImportResponse response = service.importStatement(1L,
                "<statement><transaction><type>deposit</type><amount>25.50</amount>"
                + "<description>Local execution fixture</description></transaction></statement>");

        assertThat(response.getStatus()).isEqualTo("SUCCESS");
        assertThat(response.getTransactionsImported()).isEqualTo(1);
        assertThat(account.getBalance()).isEqualByComparingTo(new BigDecimal("1025.50"));
    }
}
